drills.improve:
Set a timeout, bound the attempts, retry only transient failures (connection errors, timeouts, 5xx, and 429 throttling) with exponential backoff and full jitter, and send an idempotency key so the server can recognize a repeat. This assumes the payment API supports idempotency keys, as most do.

import random
import time

import requests

URL = "https://payments.example.com/charge"

def charge(order_id, amount, attempts=5):
    headers = {"Idempotency-Key": f"charge-{order_id}"}
    for attempt in range(attempts):
        try:
            resp = requests.post(URL, json={"order": order_id, "amount": amount},
                                 headers=headers, timeout=5)
            if resp.status_code < 500 and resp.status_code != 429:
                resp.raise_for_status()  # other 4xx: caller error, do not retry
                return resp.json()
        except (requests.ConnectionError, requests.Timeout):
            pass
        time.sleep(random.uniform(0, min(20, 0.1 * 2 ** attempt)))  # full jitter
    raise RuntimeError(f"charge {order_id} failed after {attempts} attempts")

